class Solution {
public:
    int maxRectangleArea(vector<vector<int>>& points) {
        set<pair<int, int>> ptSet;
        for (const auto& p : points) ptSet.insert({p[0], p[1]});
        int maxArea = -1;
        int n = points.size();

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 == x2 || y1 == y2) continue;
                if (ptSet.count({x1, y2}) && ptSet.count({x2, y1})) {
                    int minX = min(x1, x2), maxX = max(x1, x2);
                    int minY = min(y1, y2), maxY = max(y1, y2);
                    bool valid = true;
                    for (const auto& p : points) {
                        int px = p[0], py = p[1];
                        if (px >= minX && px <= maxX && py >= minY && py <= maxY) {
                            if ((px == x1 && py == y1) || (px == x2 && py == y2) ||
                                (px == x1 && py == y2) || (px == x2 && py == y1)) continue;
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        maxArea = max(maxArea, (maxX - minX) * (maxY - minY));
                    }
                }
            }
        }
        return maxArea;
    }
};

class Solution {
    public int maxRectangleArea(int[][] points) {
        Set<String> ptSet = new HashSet<>();
        for (int[] p : points) ptSet.add(p[0] + "," + p[1]);
        int maxArea = -1;
        int n = points.length;

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];
                if (x1 == x2 || y1 == y2) continue;
                if (ptSet.contains(x1 + "," + y2) && ptSet.contains(x2 + "," + y1)) {
                    int minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
                    int minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
                    boolean valid = true;
                    for (int[] p : points) {
                        int px = p[0], py = p[1];
                        if (px >= minX && px <= maxX && py >= minY && py <= maxY) {
                            if ((px == x1 && py == y1) || (px == x2 && py == y2) ||
                                (px == x1 && py == y2) || (px == x2 && py == y1)) continue;
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        maxArea = Math.max(maxArea, (maxX - minX) * (maxY - minY));
                    }
                }
            }
        }
        return maxArea;
    }
}

